package com.jbrempresa.backend.entity;
import java.time.LocalDateTime; import com.fasterxml.jackson.annotation.JsonFormat; import jakarta.persistence.*;
@Entity @Table(name="provincias") public class Provincia {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="prv_id") private Long prvId; @Column(name="emp_id",nullable=false) private Long empId; @Column(name="pai_id",nullable=false) private Long paiId; @Column(name="prv_cod",nullable=false,length=10) private String prvCod; @Column(name="prv_nom",nullable=false,length=100) private String prvNom; @Column(name="prv_usu_mov",nullable=false,length=50) private String prvUsuMov; @JsonFormat(pattern="dd/MM/yyyy HH:mm:ss") @Column(name="prv_fec_mov",nullable=false) private LocalDateTime prvFecMov; @Column(name="prv_act",nullable=false) private Boolean prvAct;
 public Long getPrvId(){return prvId;} public void setPrvId(Long v){prvId=v;} public Long getEmpId(){return empId;} public void setEmpId(Long v){empId=v;} public Long getPaiId(){return paiId;} public void setPaiId(Long v){paiId=v;} public String getPrvCod(){return prvCod;} public void setPrvCod(String v){prvCod=v;} public String getPrvNom(){return prvNom;} public void setPrvNom(String v){prvNom=v;} public String getPrvUsuMov(){return prvUsuMov;} public void setPrvUsuMov(String v){prvUsuMov=v;} public LocalDateTime getPrvFecMov(){return prvFecMov;} public void setPrvFecMov(LocalDateTime v){prvFecMov=v;} public Boolean getPrvAct(){return prvAct;} public void setPrvAct(Boolean v){prvAct=v;}
}
